#!/usr/bin/env node

// Bare `npm install` of the SDK must do nothing invasive: no network, no file
// writes. Print one hint pointing at the explicit, consent-gated setup command.
// Stay silent under CI or when stdout isn't a terminal (logs/pipes).
if (!process.env.CI && process.stdout.isTTY) {
  console.log(
    'RUN.world SDK installed. Run `npx rundot-sdk-setup` to copy docs and configure your AI agent files.',
  );
}
